  { id: 'total', name: 'Сумма', width: 130, align: 'end', render: (order) => "'`${order.total.toLocaleString('"'ru-RU')} ₽"'` },
];

const defaultColumnOrder: ColumnId[] = columns.map((column) => column.id);

const moneyFormatter = new Intl.NumberFormat('"'ru-RU', {
  style: 'currency',
