120	export function App() {
121	  const [collapsed, setCollapsed] = useState(false);
122	  const [activeSection, setActiveSection] = useState<SectionId>('orders');
123	  const [selectedRowIds, setSelectedRowIds] = useState<string[]>([]);
124	  const [lastSelectedIndex, setLastSelectedIndex] = useState<number | null>(null);
125	  const [grouping, setGrouping] = useState<'none' | 'status'>('status');
126	  const [columnOrder, setColumnOrder] = useState<ColumnId[]>(defaultColumnOrder);
127	  const [dragOverColumn, setDragOverColumn] = useState<ColumnId | null>(null);
128	  const [draggingColumn, setDraggingColumn] = useState<ColumnId | null>(null);
129	
130	  const orderedColumns = useMemo(
131	    () => columnOrder.map((id) => columns.find((column) => column.id === id)!),
132	    [columnOrder],
133	  );
134	
135	  const rowsByStatus = useMemo(() => {
136	    if (grouping === 'none') {
137	      return orders.map((order) => [order]);
138	    }
139	    return statusOrder.map((status) =>
140	      orders.filter((order) => order.status === status),
141	    );
142	  }, [grouping]);
143	
144	  const tableData = useMemo<OrderRow[]>(() => {
145	    if (grouping === 'none') {
146	      return orders.map((order) => ({ ...order }));
147	    }
148	    return rowsByStatus.flatMap((statusRows) => {
149	      const status = statusRows[0]?.status as OrderStatus;
150	      return [
151	        {
152	          id: `group-${status}`,
153	          number: '',
154	          customer: '',
155	          createdAt: '',
156	          total: 0,
157	          status,
158	          __group: status,
159	        },
160	        ...statusRows,
161	      ];
162	    });
163	  }, [grouping, rowsByStatus]);
164	
165	  const clearSelection = useCallback(() => {
166	    setSelectedRowIds([]);
167	    setLastSelectedIndex(null);
168	  }, []);
169	
170	  const handleRowClick = useCallback(
171	    (row: OrderRow, index: number, event: MouseEvent<HTMLTableRowElement>) => {
172	      if (isGroupRow(row)) {
173	        return;
174	      }
175	
176	      const isRangeSelect = event.shiftKey;
177	      const isMultiSelect = event.metaKey || event.ctrlKey;
178	      const isAlreadySelected = selectedRowIds.includes(row.id);
179	      let nextSelectedIds: string[];
180	
181	      if (isRangeSelect && lastSelectedIndex !== null) {
182	        const start = Math.min(lastSelectedIndex, index);
183	        const end = Math.max(lastSelectedIndex, index);
184	        const rangeIds = tableData
185	          .slice(start, end + 1)
186	          .filter((item) => !isGroupRow(item))
187	          .map((item) => item.id);
188	        nextSelectedIds = isAlreadySelected
189	          ? selectedRowIds.filter((id) => !rangeIds.includes(id))
190	          : Array.from(new Set([...selectedRowIds, ...rangeIds]));
191	      } else if (isMultiSelect) {
192	        nextSelectedIds = isAlreadySelected
193	          ? selectedRowIds.filter((id) => id !== row.id)
194	          : [...selectedRowIds, row.id];
195	      } else {
196	        nextSelectedIds = [row.id];
197	      }
198	
199	      setSelectedRowIds(nextSelectedIds);
200	      setLastSelectedIndex(index);
201	    },
202	    [tableData, lastSelectedIndex, selectedRowIds],
203	  );
204	
205	  const handleHeaderDragStart = useCallback((columnId: ColumnId, event: DragEvent<HTMLDivElement>) => {
206	    event.dataTransfer.setData('text/plain', columnId);
207	    event.dataTransfer.effectAllowed = 'move';
208	    setDraggingColumn(columnId);
209	  }, []);
210	
240	  const handleHeaderDragEnd = useCallback(() => {
241	    setDraggingColumn(null);
242	    setDragOverColumn(null);
243	  }, []);
244	
245	  const resetColumnOrder = useCallback(() => setColumnOrder(defaultColumnOrder), []);
246	  const selectAllVisible = useCallback(
247	    () => setSelectedRowIds(orders.map((order) => order.id)),
248	    [],
249	  );
250	
251	  const isRowSelected = (order: Order) => selectedRowIds.includes(order.id);
252	
253	  const tableColumns: TableColumnConfig<OrderRow>[] = orderedColumns.map((column) => ({
254	    id: column.id,
255	    name: () => (
256	      <div
257	        className={`orders-table__header${draggingColumn === column.id ? ' orders-table__header_dragging' : ''}${dragOverColumn === column.id ? ' orders-table__header_drop-target' : ''}`}
258	        draggable
259	        onDragStart={(event) => handleHeaderDragStart(column.id, event)}
260	        onDragOver={(event) => handleHeaderDragOver(column.id, event)}
261	        onDrop={() => handleHeaderDrop(column.id)}
262	        onDragEnd={handleHeaderDragEnd}
263	        title="Перетащите, чтобы изменить порядок колонок"
264	      >
265	        <span className="orders-table__header-name">{column.name}</span>
266	        <span aria-hidden className="orders-table__drag-handle">⋮⋮</span>
267	      </div>
268	    ),
269	    align: column.align,
270	    width: column.width,
271	    template: (row) =>
272	      isGroupRow(row)
273	        ? column.id === 'number'
274	          ? `${orderStatuses[row.__group]} · ${rowsByStatus.find((statusRows) => statusRows[0]?.status === row.__group)?.length || 0} заказов`
275	          : ''
276	        : column.render(row),
277	  }));
278	
279	  tableColumns.unshift({
280	    id: 'status',
281	    name: 'Статус',
282	    width: 170,
283	    template: (row) =>
284	      isGroupRow(row) ? (
285	        <Label theme={statusLabels[row.__group].tone}>
286	          {orderStatuses[row.__group]}
287	        </Label>
288	      ) : (
289	        <Label theme={statusLabels[row.status].tone}>{orderStatuses[row.status]}</Label>
290	      ),
291	  });
292	
293	  const selectedSummary = selectedRowIds.length
294	    ? `Выбрано заказов: ${selectedRowIds.length}`
295	    : 'Кликните строку, Shift — диапазон, Ctrl/Cmd — добавить';
296	
297	  const sectionContent = activeSection === 'orders' ? (
298	    <div className="orders-panel">
299	      <div className="orders-panel__toolbar">
300	        <SegmentedRadioGroup
301	          value={grouping}
302	          onUpdate={(value) => setGrouping(value as typeof grouping)}
303	        >
304	          <SegmentedRadioGroup.Option value="status">По статусу</SegmentedRadioGroup.Option>
305	          <SegmentedRadioGroup.Option value="none">Без групп</SegmentedRadioGroup.Option>
306	        </SegmentedRadioGroup>
307	        <div className="orders-panel__toolbar-actions">
308	          <button type="button" className="dashboard-button" onClick={selectAllVisible}>
309	            Выбрать все
310	          </button>
311	          <button type="button" className="dashboard-button" onClick={clearSelection}>
312	            Снять выбор
313	          </button>
314	          <button type="button" className="dashboard-button dashboard-button_ghost" onClick={resetColumnOrder}>
315	            Сбросить колонки
316	          </button>
317	        </div>
318	      </div>
319	      <div className="orders-panel__hint">{selectedSummary}</div>
320	      <div className="orders-table-wrap">
321	        <Table
322	          className="orders-table"
323	          data={tableData}
324	          columns={tableColumns}
325	          getRowId={(row) => row.id}
326	          getRowDescriptor={(row) => ({
327	            classNames: [isRowSelected(row) ? 'orders-table__row_selected' : ''],
328	            interactive: true,
329	          })}
330	          onRowClick={handleRowClick}
331	          emptyMessage="Заказов нет"
332	          width="max"
333	        />
334	      </div>
335	    </div>
336	  ) : (
337	    <div className="placeholder-panel">
338	      <Text variant="body-1">
339	        Раздел «{getSectionHeader(activeSection)}» доступен как часть навигации.
340	      </Text>
345	    <div className={`dashboard${collapsed ? ' dashboard_nav-collapsed' : ''}`}>
346	      <aside className="dashboard-sidebar" aria-label="Основная навигация">
347	        <button
348	          type="button"
349	          className="dashboard-brand"
350	          onClick={() => setCollapsed((value) => !value)}
351	          aria-expanded={!collapsed}
352	        >
