}

.dashboard-nav__item_active {
  background: var(--admin-selection);
  color: var(--admin-accent);
}

.dashboard-nav__item_active .dashboard-nav__icon {
  color: var(--admin-accent);
}

.dashboard-nav {
  display: flex;
  flex-direction: column;
  gap: 4px;
  flex: 1;
  min-height: 0;
  overflow-y: auto;
}

.dashboard-collapse {
  margin-top: 12px;
  flex-shrink: 0;
}

.dashboard-collapse__arrow {
  width: 20px;
  text-align: center;
  font-size: 18px;
  line-height: 1;
}

.dashboard-nav__text,
.dashboard-brand__text,
.dashboard-collapse__text {
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.dashboard_nav-collapsed .dashboard-nav__text,
.dashboard_nav-collapsed .dashboard-brand__text,
.dashboard_nav-collapsed .dashboard-collapse__text,
.dashboard_nav-collapsed .dashboard-nav__item,
.dashboard_nav-collapsed .dashboard-brand,
.dashboard_nav-collapsed .dashboard-collapse {
  width: auto;
}

.dashboard_nav-collapsed .dashboard-nav__item,
.dashboard_nav-collapsed .dashboard-brand,
.dashboard_nav-collapsed .dashboard-collapse {
  justify-content: center;
  padding: 0;
}

.dashboard_nav-collapsed .dashboard-brand {
  margin-left: auto;
  margin-right: auto;
}

.dashboard-content {
  display: flex;
  flex: 1;
  min-width: 0;
  flex-direction: column;
  padding: 24px 28px;
}

.dashboard-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 20px;
}

.orders-panel,
.placeholder-panel {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-width: 0;
  min-height: 0;
  padding: 20px;
  border: 1px solid var(--admin-line);
  border-radius: 16px;
  background: var(--admin-surface);
  box-shadow: 0 4px 24px rgba(15, 23, 42, .05);
}

.placeholder-panel {
  justify-content: center;
  align-items: center;
  gap: 8px;
}

.orders-panel__toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
}

.orders-panel__toolbar-actions {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.dashboard-button {
  height: 36px;
  padding: 0 14px;
  border: 1px solid var(--admin-line);
  border-radius: 8px;
  background: var(--admin-surface);
  color: var(--admin-text);
  font: inherit;
  cursor: pointer;
}

.dashboard-button:hover {
  background: var(--admin-surface-hover);
}

.dashboard-button_ghost {
  color: var(--admin-text-secondary);
}

.orders-panel__hint {
  margin: 12px 0 16px;
  color: var(--admin-text-secondary);
  font-size: 13px;
}

.orders-table-wrap {
  flex: 1;
  min-height: 0;
  overflow: auto;
  border: 1px solid var(--admin-line);
  border-radius: 10px;
}

.orders-table table {
  width: 100%;
  min-width: 760px;
}

.orders-table__header {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  min-height: 28px;
  cursor: grab;
  user-select: none;
}

.orders-table__header:active {
  cursor: grabbing;
}

.orders-table__drag-handle {
  margin-left: auto;
  color: var(--admin-text-secondary);
  font-size: 11px;
  letter-spacing: -2px;
  opacity: .45;
}

.orders-table__header:hover .orders-table__drag-handle,
.orders-table__header_dragging .orders-table__drag-handle {
  opacity: 1;
}

.orders-table__header_dragging {
  opacity: .55;
}

.orders-table__header_drop-target {
  box-shadow: inset -3px 0 0 var(--admin-accent);
}

.orders-table__row_selected {
  background: var(--admin-selection) "'!important;
}

.orders-table__row_group-header {
  background: var(--g-color-base-simple-hover, #f5f6f8) !important;
  font-weight: 600;
}

.orders-table__row_group-first {
  box-shadow: inset 2px 0 0 var(--admin-accent);
}

.orders-table .g-table__cell {
  vertical-align: middle;
}

@media (max-width: 720px) {
  .dashboard {
    flex-direction: column;
  }

  .dashboard-sidebar {
    position: static;
    flex: 0 0 auto;
    width: 100%;
    height: auto;
    flex-direction: row;
    align-items: center;
    padding: 10px;
    border-right: 0;
    border-bottom: 1px solid var(--admin-line);
  }

  .dashboard-brand {
    margin: 0;
  }

  .dashboard-nav {
    flex-direction: row;
    gap: 4px;
    overflow-x: auto;
  }

  .dashboard-collapse {
    margin: 0;
    width: auto;
  }

  .dashboard-content {
    padding: 16px;
  }

  .orders-panel {
    padding: 12px;
  }
}
